import{_ as i,o,c as a,a2 as t}from"./chunks/framework.DNL3hc5c.js";const g=JSON.parse('{"title":"🤝 Magma Computing Solutions: Professional Services","description":"","frontmatter":{},"headers":[],"relativePath":"doc/8-project-and-support/commercial.md","filePath":"doc/8-project-and-support/commercial.md"}'),r={name:"doc/8-project-and-support/commercial.md"};function n(s,e,l,c,m,u){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="🤝-magma-computing-solutions-professional-services" tabindex="-1">🤝 Magma Computing Solutions: Professional Services <a class="header-anchor" href="#🤝-magma-computing-solutions-professional-services" aria-label="Permalink to &quot;🤝 Magma Computing Solutions: Professional Services&quot;">​</a></h1><p>Tempo is a high-performance, precision date-time library maintained by <strong>Magma Computing Solutions</strong>. We offer a range of professional services and private extensions to help teams build robust, time-sensitive applications.</p><h2 id="🚀-our-services" tabindex="-1">🚀 Our Services <a class="header-anchor" href="#🚀-our-services" aria-label="Permalink to &quot;🚀 Our Services&quot;">​</a></h2><h3 id="🧩-custom-plugin-development" tabindex="-1">🧩 Custom Plugin Development <a class="header-anchor" href="#🧩-custom-plugin-development" aria-label="Permalink to &quot;🧩 Custom Plugin Development&quot;">​</a></h3><p>Need a specialized plugin for your industry? We design and implement high-performance Tempo extensions such as:</p><ul><li><strong>Financial Tickers</strong>: Real-time market-aware pulses with weekend/holiday suppression.</li><li><strong>Production Timelines</strong>: Complex shift-based scheduling and resource allocation generators.</li><li><strong>Custom Terms</strong>: Domain-specific date ranges (e.g., academic years, retail seasons, or medical billing cycles).</li></ul><h3 id="🏛️-architecture-migration-consulting" tabindex="-1">🏛️ Architecture &amp; Migration Consulting <a class="header-anchor" href="#🏛️-architecture-migration-consulting" aria-label="Permalink to &quot;🏛️ Architecture &amp; Migration Consulting&quot;">​</a></h3><p>Transitioning from legacy libraries like <strong>Moment.js</strong> or <strong>Luxon</strong>? Our team can:</p><ul><li>Audit your existing date-time logic for <code>Temporal</code> compatibility.</li><li>Perform high-fidelity migrations of complex &quot;relative time&quot; calculations.</li><li>Optimize performance for large-scale data processing.</li></ul><h3 id="🛡️-enterprise-support-commercial-extensions" tabindex="-1">🛡️ Enterprise Support &amp; Commercial Extensions <a class="header-anchor" href="#🛡️-enterprise-support-commercial-extensions" aria-label="Permalink to &quot;🛡️ Enterprise Support &amp; Commercial Extensions&quot;">​</a></h3><p>For mission-critical applications, we provide:</p><ul><li>Priority commercial support and SLA guarantees.</li><li>Security auditing and bespoke feature engineering.</li><li>Custom enterprise plugins tailored to private infrastructures.</li></ul><hr><h2 id="📬-contact-us" tabindex="-1">📬 Contact Us <a class="header-anchor" href="#📬-contact-us" aria-label="Permalink to &quot;📬 Contact Us&quot;">​</a></h2><p>Ready to discuss your project? Get in touch with our engineering team:</p><ul><li><strong>Email</strong>: <a href="mailto:contact@magmacomputing.com.au" target="_blank" rel="noreferrer">contact@magmacomputing.com.au</a></li><li><strong>GitHub</strong>: <a href="https://github.com/magmacomputing" target="_blank" rel="noreferrer">github.com/magmacomputing</a></li></ul><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Tempo Core is 100% open source under the MIT license. Our professional services are designed to complement the open-source library with deep domain expertise, custom plugin engineering, and enterprise SLA support.</p></div>',18)])])}const d=i(r,[["render",n]]);export{g as __pageData,d as default};
